function normalize(game,platform='') {
  game=String(game||'').toLowerCase();
  if(game==='dayz')game=/ps|playstation/i.test(platform)?'dayz_ps':/xbox/i.test(platform)?'dayz_xbox':'dayz_pc';
  const aliases={'arma_reforger':'arma','arma reforger':'arma','ark survival ascended':'ark','ark survival evolved':'ark','conan exiles':'conan','7 days to die':'7dtd','7 days to dea':'7dtd'};
